import json
with open('transcript.jsonl') as f:
    for line in f:
        d = json.loads(line)
        t = d.get('type')
        if t in ('assistant','user'):
            msg = d.get('message',{})
            content = msg.get('content')
            if isinstance(content, list):
                for c in content:
                    if c.get('type')=='tool_use':
                        print('TOOL_USE', c.get('name'), json.dumps(c.get('input'))[:300])
                    elif c.get('type')=='tool_result':
                        cont = c.get('content')
                        s = json.dumps(cont)[:300]
                        print('TOOL_RESULT', s)
                    elif c.get('type')=='text':
                        print('TEXT', c.get('text')[:300])
